import{_ as n,C as s,o as e,c as d,j as i,a as t,E as l,a2 as r}from"./chunks/framework.C21TwvGF.js";const S=JSON.parse(`{"title":"3-dars (Mentor). Axborot o‘lchov birliklari va fayl turlari. Windows operatsion tizimida fayl hamda papkalar yaratish. Tezkor tugmalar (Hot keys)","description":"","frontmatter":{"title":"3-dars (Mentor). Axborot o‘lchov birliklari va fayl turlari. Windows operatsion tizimida fayl hamda papkalar yaratish. Tezkor tugmalar (Hot keys)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":1,"link":"/mentor/8-sinf-cs/hafta-01/"},"g":3,"title":"Axborot o‘lchov birliklari va fayl turlari. Windows operatsion tizimida fayl hamda papkalar yaratish. Tezkor tugmalar (Hot keys)","lead":"Nega kompyuterda 1 kilobayt 1000 emas, balki 1024 baytga teng? Har bir fayl ortida qanday kengaytma yashiringan va nima uchun professional dasturchilar sichqonchadan ko'ra tezkor tugmalarni (Hot keys) afzal ko'rishadi? Ushbu darsda axborot hisob-kitoblari va fayllarni boshqarish sirlarini o'rganamiz.","slide":"/slaydlar/8-sinf-cs/hafta-01/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-01/dars-3-test.html","student_link":"/8-sinf-cs/hafta-01/dars-3","tabs":[{"g":1,"link":"/mentor/8-sinf-cs/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/8-sinf-cs/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/8-sinf-cs/hafta-01/dars-3","current":true}],"prev":{"g":2,"title":"Operatsion tizimlar va Windows muhitida ishlash","link":"/mentor/8-sinf-cs/hafta-01/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-01/dars-3.md","filePath":"mentor/8-sinf-cs/hafta-01/dars-3.md"}`),h={name:"mentor/8-sinf-cs/hafta-01/dars-3.md"},c={class:"blk"},g={id:"_1-dars-rejasi",tabindex:"-1"},m={class:"blk"},u={id:"_2-dars-konspekti",tabindex:"-1"},y={class:"blk"},b={id:"_3-kod-amaliy-buyruqlar",tabindex:"-1"},k={class:"blk"},p={id:"_4-amaliy-topshiriqlar",tabindex:"-1"},f={class:"blk"},q={id:"_5-tezkor-nazorat",tabindex:"-1"},v={class:"blk"},x={id:"_6-uyga-vazifa",tabindex:"-1"};function _(z,a,C,T,B,j){const o=s("Icon");return e(),d("div",null,[a[18]||(a[18]=i("p",null,[i("strong",null,"Hafta:"),t(" 1 · "),i("strong",null,"Davomiyligi:"),t(" 80 daqiqa · "),i("strong",null,"Turi:"),t(" nazariya + amaliy ko'nikmalar · "),i("strong",null,"I-bob"),t(", 3-dars")],-1)),i("div",c,[i("h2",g,[l(o,{name:"file-text"}),a[0]||(a[0]=t(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r('<p><strong>Maqsad:</strong> o&#39;quvchilarda axborotning eng kichik birligidan (bit, bayt) tortib yirik o&#39;lchovlarigacha (KB, MB, GB, TB) bo&#39;lgan ierarxiyani hisoblash, fayl tushunchasi, fayl nomlari va kengaytmalari (.txt, .docx, .jpg, .png, .mp4, .exe, .py), Windowsda fayl va papkalarni yaratish, tartiblash, nusxalash, ko&#39;chirish, o&#39;chirish, qayta tiklash hamda eng muhim tezkor tugmalar (Ctrl+C, Ctrl+V, Ctrl+X, Ctrl+Z, Ctrl+A, F2, Delete, Shift+Delete) bilan tez va xatosiz ishlash ko&#39;nikmalarini shakllantirish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Axborot o&#39;lchov birliklarini (bit, bayt, KB, MB, GB, TB) biladi va bir-biriga aylantira oladi (masalan, 1 MB = 1024 KB).</li><li>Fayl nomi va kengaytmasi vazifasini tushuntiradi, asosiy fayl turlarini taniydi.</li><li>Windowsda fayl va papka tuzilmasini daraxtsimon ierarxiya ko&#39;rinishida tushunadi va to&#39;g&#39;ri tashkil qiladi.</li><li>Fayl va papkalarni sichqonchasiz, klaviaturaning tezkor tugmalari (Ctrl+C, Ctrl+V, Ctrl+X, Ctrl+Z, F2) orqali professional boshqaradi.</li><li>Savatcha (Recycle Bin) va to&#39;liq o&#39;chirish (Shift+Delete) xavfsizlik qoidalarini biladi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>1–2-darslarni takrorlash (arxitektura, Windows interfeysi). «Bitta fotosurat kompyuter xotirasida qanday saqlanadi?» muammoli savol</td></tr><tr><td>10–30 daq</td><td>Yangi mavzu: Nazariya</td><td>Axborot o&#39;lchov birliklari (ikkilik tizim, 1024 koeffitsienti), fayl turlari va kengaytmalari, papkalar daraxti</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Ko&#39;rish qobiliyatini yaxshilovchi mashqlar</td></tr><tr><td>35–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>File Explorer&#39;da papkalar tuzilmasini yaratish, fayl kengaytmalarini ko&#39;rsatish, tezkor tugmalar bilan manipulyatsiya</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol va hisoblash masalasi</td></tr><tr><td>75–80 daq</td><td>Hafta xulosasi va uyga vazifa</td><td>1-hafta umumiy xulosasi va uy vazifasi</td></tr></tbody></table><hr>',5))]),i("div",m,[i("h2",u,[l(o,{name:"file-text"}),a[3]||(a[3]=t(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_2-1-axborot-o-lchov-birliklari" tabindex="-1">2.1. Axborot o&#39;lchov birliklari <a class="header-anchor" href="#_2-1-axborot-o-lchov-birliklari" aria-label="Permalink to &quot;2.1. Axborot o&#39;lchov birliklari&quot;">​</a></h3><p>Kompyuter faqat elektr signallarini — tok bor (1) yoki tok yo&#39;q (0) holatlarini tushunadi.</p><ul><li><strong>Bit (Binary digit):</strong> Axborotning eng kichik o&#39;lchov birligi. U faqat <code>0</code> yoki <code>1</code> qiymatini qabul qiladi.</li><li><strong>Bayt (Byte):</strong> 8 ta bitning birlashmasi. 1 bayt xotiraga klaviaturadagi ixtiyoriy 1 ta harf, raqam yoki belgi (masalan, «A» yoki «7») sig&#39;adi.</li></ul><p>Kompyuterda ikkilik sanoq tizimi ($2^{10} = 1024$) ishlatilgani sababli keyingi birliklar 1000 emas, <strong>1024</strong> marta kattalashadi:</p><ul><li><strong>1 KB (Kilobayt)</strong> = 1024 bayt (~1 varaq toza matn).</li><li><strong>1 MB (Megabayt)</strong> = 1024 KB (~1 ta kitob yoki 1 daqiqalik MP3 musiqa).</li><li><strong>1 GB (Gigabayt)</strong> = 1024 MB (~1 ta to&#39;liq sifatli film).</li><li><strong>1 TB (Terabayt)</strong> = 1024 GB (~1000 ta film yoki butun boshli katta kutubxona).</li></ul><p><em>Hisoblash qoidasi:</em> Kichik birlikdan kattasiga o&#39;tishda $1024$ ga bo&#39;linadi, kattasidan kichigiga o&#39;tishda $1024$ ga ko&#39;paytiriladi.</p><h3 id="_2-2-fayl-va-uning-turlari" tabindex="-1">2.2. Fayl va uning turlari <a class="header-anchor" href="#_2-2-fayl-va-uning-turlari" aria-label="Permalink to &quot;2.2. Fayl va uning turlari&quot;">​</a></h3><p><strong>Fayl</strong> — kompyuterning tashqi xotirasida (SSD yoki HDD da) umumiy nom bilan saqlanadigan, ma&#39;lum turdagi axborotlar to&#39;plami. Har bir fayl ikkita asosiy qismdan iborat bo&#39;lib, ular nuqta <code>.</code> bilan ajratiladi: <code>fayl_nomi.kengaytma</code> (masalan: <code>referat.docx</code>, <code>foto.jpg</code>, <code>dastur.py</code>).</p><ul><li><strong>Fayl nomi:</strong> Foydalanuvchi tomonidan beriladi (istalgan ma&#39;noli nom).</li><li><strong>Kengaytma (Extension):</strong> Nuqtadan keyingi 3–4 ta harf bo&#39;lib, faylning turini (formati) va uni qaysi dastur ochishini belgilaydi.</li></ul><p>Eng ko&#39;p ishlatiladigan kengaytmalar:</p><ul><li><strong>Matnli fayllar:</strong> <code>.txt</code> (oddiy matn), <code>.docx</code> (Word hujjati), <code>.pdf</code> (elektron kitob/hujjat).</li><li><strong>Grafik fayllar (Tasvirlar):</strong> <code>.jpg</code> / <code>.jpeg</code> (fotosuratlar), <code>.png</code> (shaffof fonli tasvir), <code>.svg</code> (vektorli chizma).</li><li><strong>Ovozli va video fayllar:</strong> <code>.mp3</code>, <code>.wav</code> (musiqa); <code>.mp4</code>, <code>.mkv</code> (video).</li><li><strong>Dastur va kod fayllari:</strong> <code>.exe</code> (ishga tushuvchi dastur), <code>.py</code> (Python kodi), <code>.html</code> (veb-sahifa), <code>.zip</code> / <code>.rar</code> (arxiv).</li></ul><h3 id="_2-3-papka-folder-va-fayl-tizimi-tuzilmasi" tabindex="-1">2.3. Papka (Folder) va fayl tizimi tuzilmasi <a class="header-anchor" href="#_2-3-papka-folder-va-fayl-tizimi-tuzilmasi" aria-label="Permalink to &quot;2.3. Papka (Folder) va fayl tizimi tuzilmasi&quot;">​</a></h3><p><strong>Papka (Katalog / Directory)</strong> — fayllarni mavzular bo&#39;yicha saralab, tartibli saqlash uchun mo&#39;ljallangan «konvert» yoki «jild». Papka ichida boshqa papkalar (ichki papkalar — subfolders) bo&#39;lishi mumkin. Bu tuzilma <strong>daraxtsimon ierarxiya</strong> deyiladi. Faylning to&#39;liq manzili (Path) uning qaysi disk va qaysi papkalar ichidaligini ko&#39;rsatadi: <code>C:\\Oquvchi\\Darslar\\8-sinf\\1-dars.docx</code></p><h3 id="_2-4-fayl-va-papkalar-ustida-amallar" tabindex="-1">2.4. Fayl va papkalar ustida amallar <a class="header-anchor" href="#_2-4-fayl-va-papkalar-ustida-amallar" aria-label="Permalink to &quot;2.4. Fayl va papkalar ustida amallar&quot;">​</a></h3><p>Windowsda fayl va papkalar bilan ishlashning 5 ta oltin amali:</p><ol><li><strong>Yaratish:</strong> Sichqonchaning o&#39;ng tugmasi → New (Yaratish) → Folder / Text Document.</li><li><strong>Nomlash va qayta nomlash:</strong> Faylni tanlab, <code>F2</code> tugmasini bosish.</li><li><strong>Nusxalash (Copy):</strong> Asl nusxani o&#39;z joyida qoldirib, uning dublikatini yaratish (<code>Ctrl + C</code>).</li><li><strong>Ko&#39;chirish (Cut):</strong> Faylni avvalgi joyidan sug&#39;urib olib, yangi joyga ko&#39;chirish (<code>Ctrl + X</code>).</li><li><strong>O&#39;chirish (Delete):</strong><ul><li><code>Delete</code>: Faylni Savatchaga (Recycle Bin) yuboradi (qaytarib olish mumkin).</li><li><code>Shift + Delete</code>: Faylni Savatchani aylanib o&#39;tib, xotiradan butunlay o&#39;chiradi (ehtiyot bo&#39;lish shart!).</li></ul></li></ol><h3 id="_2-5-eng-muhim-tezkor-tugmalar-hot-keys" tabindex="-1">2.5. Eng muhim tezkor tugmalar (Hot keys) <a class="header-anchor" href="#_2-5-eng-muhim-tezkor-tugmalar-hot-keys" aria-label="Permalink to &quot;2.5. Eng muhim tezkor tugmalar (Hot keys)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tugmalar</th><th>Vazifasi</th></tr></thead><tbody><tr><td><code>Ctrl + C</code></td><td>Tanlangan obyektni nusxalash (Copy)</td></tr><tr><td><code>Ctrl + X</code></td><td>Tanlangan obyektni qirqib olish (Cut)</td></tr><tr><td><code>Ctrl + V</code></td><td>Nusxalangan yoki qirqilgan obyektni qo&#39;yish (Paste)</td></tr><tr><td><code>Ctrl + Z</code></td><td>Oxirgi xato amalni bekor qilish (Undo)</td></tr><tr><td><code>Ctrl + A</code></td><td>Papkadagi barcha fayllarni bir zumda tanlash (Select All)</td></tr><tr><td><code>F2</code></td><td>Tanlangan fayl yoki papka nomini o&#39;zgartirish (Rename)</td></tr><tr><td><code>Delete</code></td><td>Savatchaga o&#39;chirish</td></tr><tr><td><code>Shift + Delete</code></td><td>Butunlay qayta tiklanmas qilib o&#39;chirish</td></tr><tr><td><code>Win + E</code></td><td>Fayl boshqaruvchisini (File Explorer) ochish</td></tr></tbody></table><hr>',19))]),i("div",y,[i("h2",b,[l(o,{name:"file-text"}),a[6]||(a[6]=t(" 3. Kod / Amaliy buyruqlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-kod-amaliy-buyruqlar","aria-label":'Permalink to "<Icon name="file-text" /> 3. Kod / Amaliy buyruqlar"'},"​",-1))]),a[8]||(a[8]=r(`<p>Amaliy mashg&#39;ulotda papkalar tuzilmasini yaratish mashqi:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>D:\\ (yoki C:\\Users\\Oquvchi\\Documents)</span></span>
<span class="line"><span>└── CS_Foundation\\</span></span>
<span class="line"><span>    ├── 01_Hujjatlar\\</span></span>
<span class="line"><span>    │   └── reja.txt</span></span>
<span class="line"><span>    ├── 02_Rasmlar\\</span></span>
<span class="line"><span>    │   └── kompyuter.png</span></span>
<span class="line"><span>    └── 03_Loyiha\\</span></span>
<span class="line"><span>        └── dastur.py</span></span></code></pre></div><p>File Explorer&#39;da fayl kengaytmalarini ko&#39;rinadigan qilish:</p><ol><li>File Explorer&#39;ni oching (<code>Win + E</code>).</li><li>Yuqori menyudan «View» (Ko&#39;rinish) → «Show» (Ko&#39;rsatish) bo&#39;limiga o&#39;ting.</li><li>«File name extensions» (Fayl nomining kengaytmalari) bandiga galochka qo&#39;ying.</li></ol><hr>`,5))]),i("div",k,[i("h2",p,[l(o,{name:"file-text"}),a[9]||(a[9]=t(" 4. Amaliy topshiriqlar ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-amaliy-topshiriqlar","aria-label":'Permalink to "<Icon name="file-text" /> 4. Amaliy topshiriqlar"'},"​",-1))]),a[11]||(a[11]=r('<h3 id="_1-topshiriq-oson" tabindex="-1">1-topshiriq (oson) <a class="header-anchor" href="#_1-topshiriq-oson" aria-label="Permalink to &quot;1-topshiriq (oson)&quot;">​</a></h3><p><code>Win + E</code> orqali «Documents» (Hujjatlar) papkasiga kiring. Klaviaturadagi <code>Ctrl + Shift + N</code> tezkor tugmalari yordamida yangi papka oching va <code>F2</code> tugmasi bilan unga <code>Mening_Darslarim</code> deb nom bering.</p><p><strong>Kutiladigan natija:</strong> «Documents» ichida <code>Mening_Darslarim</code> nomli yangi papka paydo bo&#39;ladi.</p><p><strong>Yechim:</strong></p><ol><li><code>Win + E</code> bosiladi, chap paneldan «Documents» tanlanadi.</li><li><code>Ctrl + Shift + N</code> birgalikda bosilganda yangi papka yaratiladi.</li><li>Klaviaturada darhol <code>Mening_Darslarim</code> yoziladi yoki <code>F2</code> bosilib qayta nomlanadi va <code>Enter</code> bosiladi.</li></ol><hr><h3 id="_2-topshiriq-o-rta" tabindex="-1">2-topshiriq (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-o-rta" aria-label="Permalink to &quot;2-topshiriq (o&#39;rta)&quot;">​</a></h3><p>Yaratilgan <code>Mening_Darslarim</code> papkasi ichiga kiring. Sichqonchaning o&#39;ng tugmasi orqali yangi Text Document yarating va unga <code>malumot.txt</code> nomini bering. Ushbu fayl ustida quyidagi amallarni bajaring:</p><ol><li><code>Ctrl + C</code> va <code>Ctrl + V</code> bilan uning nusxasini yarating.</li><li>Hosil bo&#39;lgan ikkinchi faylni <code>F2</code> orqali <code>malumot_nusxa.txt</code> deb qayta nomlang.</li><li><code>malumot_nusxa.txt</code> faylini tanlab <code>Delete</code> tugmasi bilan o&#39;chiring.</li><li>Savatchani (Recycle Bin) ochib, o&#39;chirilgan faylni toping va «Restore» (Qayta tiklash) buyrug&#39;i bilan o&#39;z joyiga qaytaring.</li></ol><p><strong>Kutiladigan natija:</strong> Fayl muvaffaqiyatli nusxalanadi, o&#39;chiriladi va Savatchadan qayta tiklanadi.</p><p><strong>Yechim:</strong></p><ol><li>Papka ichida bo&#39;sh joyda o&#39;ng tugma bosilib «New» → «Text Document» tanlanadi.</li><li>Fayl tanlanib <code>Ctrl + C</code>, so&#39;ngra <code>Ctrl + V</code> bosiladi.</li><li><code>F2</code> bosilib nomi <code>malumot_nusxa.txt</code> qilinadi.</li><li>Tanlanib <code>Delete</code> bosiladi. Ish stolidan «Recycle Bin» ochilib, fayl ustida o&#39;ng tugma va «Restore» bosiladi.</li></ol><hr><h3 id="_3-topshiriq-qiyin" tabindex="-1">3-topshiriq (qiyin) <a class="header-anchor" href="#_3-topshiriq-qiyin" aria-label="Permalink to &quot;3-topshiriq (qiyin)&quot;">​</a></h3><p>Axborot o&#39;lchov birliklari bo&#39;yicha quyidagi hisoblash masalasini bajaring:</p><ol><li>Bitta kompyuter diskining bo&#39;sh joyi $4 \\text{ GB}$ ni tashkil etadi.</li><li>Har bir fotosuratning o&#39;rtacha hajmi $4 \\text{ MB}$ ga teng. Ushbu diskka eng ko&#39;pi bilan nechta fotosurat sig&#39;ishini qadamma-qadam hisoblab ko&#39;rsating ($1 \\text{ GB} = 1024 \\text{ MB}$).</li></ol><p><strong>Kutiladigan natija:</strong> To&#39;g&#39;ri matematik hisob-kitob va fotosuratlar soni aniqlanadi.</p><p><strong>Yechim:</strong></p><ol><li>Gigabaytni megabaytga aylantiramiz: $$4 \\text{ GB} = 4 \\times 1024 \\text{ MB} = 4096 \\text{ MB}$$</li><li>Sig&#39;adigan rasmlar sonini topish uchun jami bo&#39;sh joyni 1 ta rasm hajmiga bo&#39;lamiz: $$\\frac{4096 \\text{ MB}}{4 \\text{ MB}} = 1024 \\text{ ta rasm}$$</li><li>Javob: Diskka aniq 1024 ta fotosurat sig&#39;adi.</li></ol><hr>',20))]),i("div",f,[i("h2",q,[l(o,{name:"file-text"}),a[12]||(a[12]=t(" 5. Tezkor nazorat ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-nazorat","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor nazorat"'},"​",-1))]),a[14]||(a[14]=r("<ol><li>Axborotning eng kichik o&#39;lchov birligi nima va 1 baytda nechta bit bor? <ul><li><em>Javob:</em> Eng kichik birlik — bit (0 yoki 1). 1 bayt = 8 bit.</li></ul></li><li>1 Megabaytda (MB) nechta Kilobayt (KB) bor? <ul><li><em>Javob:</em> 1024 KB.</li></ul></li><li>Fayl kengaytmasi nima va u qanday vazifani bajaradi? <ul><li><em>Javob:</em> Nuqtadan keyin yoziladigan 3-4 harfli format belgisi. U fayl turini va uni qaysi dastur ochishini belgilaydi.</li></ul></li><li><code>Ctrl + C</code> va <code>Ctrl + X</code> buyruqlari o&#39;rtasidagi asosiy farq nimada? <ul><li><em>Javob:</em> <code>Ctrl + C</code> nusxasini oladi (asli qoladi), <code>Ctrl + X</code> esa joyidan qirqib olib ko&#39;chiradi (asli o&#39;chadi).</li></ul></li><li><code>Shift + Delete</code> bosilganda fayl bilan nima sodir bo&#39;ladi? <ul><li><em>Javob:</em> Fayl Savatchaga tushmasdan to&#39;g&#39;ridan-to&#39;g&#39;ri diskdan butunlay o&#39;chiriladi.</li></ul></li></ol><hr>",2))]),i("div",v,[i("h2",x,[l(o,{name:"file-text"}),a[15]||(a[15]=t(" 6. Uyga vazifa ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-uyga-vazifa","aria-label":'Permalink to "<Icon name="file-text" /> 6. Uyga vazifa"'},"​",-1))]),a[17]||(a[17]=r("<ol><li>Axborot birliklarini kichigidan kattasiga qarab to&#39;g&#39;ri ketma-ketlikda yozing: <code>MB</code>, <code>Bit</code>, <code>TB</code>, <code>Bayt</code>, <code>GB</code>, <code>KB</code>.</li><li>$2 \\text{ GB}$ hajmdagi fleshkaga $512 \\text{ KB}$ hajmdagi matnli kitobchalardan nechta saqlash mumkinligini daftaringizda hisoblab chiqing.</li><li>Klaviaturadagi <code>Ctrl+C</code>, <code>Ctrl+V</code>, <code>Ctrl+X</code>, <code>Ctrl+Z</code>, <code>F2</code>, <code>Win+E</code> tugmalarining vazifasini yod oling. Vazifani bajarish vaqti: 20 daqiqa.</li></ol>",1))])])}const A=n(h,[["render",_]]);export{S as __pageData,A as default};
